function reloadState(
  overrides: Partial<{
    cannonId: CannonId;
    enemyHull: number;
    playerHull: number;
    question: Question;
    tally: DuelState['tally'];
    actionLog: readonly ActionLogEntry[];
    rng: DuelState['rng'];
    turnToken: number;
    volleyNumber: number;
    recentTemplateIds: readonly string[];
    templatesBySkill: DuelConfig['templatesBySkill'];
  }> = {},
): Extract<DuelState, { phase: 'reload' }> {
  const cannonId = overrides.cannonId ?? 'swivel_gun';
  const cannon = getCannon(cannonId);
  return {
    ...CORE_BASE,
    ...overrides,
    phase: 'reload',
    cannonId,
    question: overrides.question ?? FIXTURE_QUESTION,
    timerMs: cannon.timerMs,
    playerLoadout: PLAYER_LOADOUT,
    rivalLoadout: RIVAL_LOADOUT,
    templatesBySkill: overrides.templatesBySkill ?? FIXTURE_TEMPLATES,
  };
}

function resolvePlayerState(
  overrides: Partial<{
    cannonId: CannonId;
    enemyHull: number;
    playerHull: number;
    outcome: ShotOutcome;
    tally: DuelState['tally'];
    volleyNumber: number;
    turnToken: number;
    actionLog: readonly ActionLogEntry[];
  }> = {},
): Extract<DuelState, { phase: 'resolvePlayer' }> {
  return {
    ...CORE_BASE,
    ...overrides,
    phase: 'resolvePlayer',
    cannonId: overrides.cannonId ?? 'swivel_gun',
    outcome: overrides.outcome ?? FIXTURE_OUTCOME,
    playerLoadout: PLAYER_LOADOUT,
    rivalLoadout: RIVAL_LOADOUT,
  };
}

function rivalTurnState(
  overrides: Partial<{
    playerHull: number;
    enemyHull: number;
    tally: DuelState['tally'];
    actionLog: readonly ActionLogEntry[];
    rng: DuelState['rng'];
    turnToken: number;
    volleyNumber: number;
  }> = {},
): Extract<DuelState, { phase: 'rivalTurn' }> {
  return {
    ...CORE_BASE,
    ...overrides,
    phase: 'rivalTurn',
    playerLoadout: PLAYER_LOADOUT,
    rivalLoadout: RIVAL_LOADOUT,
  };
}

function resolveRivalState(
  overrides: Partial<{
    playerHull: number;
    enemyHull: number;
    volleyNumber: number;
    turnToken: number;
    volley: RivalVolley;
    damageToPlayer: number;
    tally: DuelState['tally'];
    actionLog: readonly ActionLogEntry[];
  }> = {},
): Extract<DuelState, { phase: 'resolveRival' }> {
  return {
    ...CORE_BASE,
    ...overrides,
    phase: 'resolveRival',
    volley: overrides.volley ?? FIXTURE_VOLLEY,
    damageToPlayer: overrides.damageToPlayer ?? 9,
    playerLoadout: PLAYER_LOADOUT,
    rivalLoadout: RIVAL_LOADOUT,
  };
}

function wrongIndex(question: Question): number {
  return (question.correctIndex + 1) % 4;
}

function snapshotArrays(state: DuelState): {
  readonly playerLoadout: readonly CannonId[];
  readonly rivalLoadout: readonly CannonId[];
  readonly recentTemplateIds: readonly string[];
  readonly actionLog: readonly ActionLogEntry[];
  readonly choices: readonly Question['choices'] | undefined;
} {
  return {
    playerLoadout: state.playerLoadout,
    rivalLoadout: state.rivalLoadout,
    recentTemplateIds: state.recentTemplateIds,
    actionLog: state.actionLog,
    choices: state.phase === 'reload' ? state.question.choices : undefined,
  };
}

/** Drive countdown → playerChoose → reload for a loadout cannon. */
function toReload(seed: number, cannonId: CannonId): Extract<DuelState, { phase: 'reload' }> {
  const countdown = createDuelState(baseConfig(seed));
  const choose = duelReducer(countdown, { type: 'ANIMATION_DONE' });
  expect(choose.phase).toBe('playerChoose');
  const reload = duelReducer(choose, { type: 'CANNON_SELECTED', cannonId });
  expect(reload.phase).toBe('reload');
  return reload as Extract<DuelState, { phase: 'reload' }>;
}

/**
 * Scripted victory path for AC-18/19/20: four perfect swivel answers with rival misses between.
 * Seed `SCRIPTED_DUEL_SEED` was selected so enemy hull (45) survives three volleys and sinks on the fourth.
 */
function driveScriptedDuel(): DuelState {
  let state: DuelState = createDuelState(baseConfig(SCRIPTED_DUEL_SEED));

  const apply = (event: DuelEvent): void => {
    state = duelReducer(state, event);
  };

  apply({ type: 'ANIMATION_DONE' }); // → playerChoose

  for (let volley = 1; volley <= 4; volley += 1) {
    apply({ type: 'CANNON_SELECTED', cannonId: 'swivel_gun' });
    expect(state.phase, `volley ${volley} reload`).toBe('reload');
    const reload = state as Extract<DuelState, { phase: 'reload' }>;
    apply({
      type: 'ANSWER_CHOSEN',
      choiceIndex: reload.question.correctIndex,
      elapsedMs: PERFECT_ELAPSED_MS,
    });
    expect(state.phase, `volley ${volley} resolvePlayer`).toBe('resolvePlayer');
    apply({ type: 'ANIMATION_DONE' });

    if (volley < 4) {
      expect(state.phase, `volley ${volley} rivalTurn`).toBe('rivalTurn');
      const hullBeforeRival = state.playerHull;
      apply({
        type: 'RIVAL_ACTION',
        volley: {
          cannonId: 'six_pounder',
          correct: false,
          elapsedMs: RIVAL_MISS_ELAPSED_MS,
        },
      });
      expect(state.phase, `volley ${volley} resolveRival`).toBe('resolveRival');
      // I-3: a standard miss must deal zero player damage (hit-on-miss would still leave the
      // player alive through three volleys and green AC-18 without this check).
      expect(state.playerHull, `volley ${volley} rival miss must not damage player`).toBe(hullBeforeRival);
      expect(state.playerHull).toBe(PLAYER_HULL);
      apply({ type: 'ANIMATION_DONE' });
      expect(state.phase, `volley ${volley} back to playerChoose`).toBe('playerChoose');
      expect(state.playerHull).toBe(PLAYER_HULL);
    }
  }

  return state;
}

