describe('T-020 duelReducer — phase transitions', () => {
  it('spec(T-020:AC-1) countdown + ANIMATION_DONE → playerChoose and turnToken += 1', () => {
    const start = createDuelState(baseConfig(1));
    expect(start.phase).toBe('countdown');
    expect(start.turnToken).toBe(0);

    const next = duelReducer(start, { type: 'ANIMATION_DONE' });

    expect(next).not.toBe(start);
    expect(next.phase).toBe('playerChoose');
    expect(next.turnToken).toBe(start.turnToken + 1);
  });

  it('spec(T-020:AC-2) CANNON_SELECTED in loadout → reload with question, timer, recent id, advanced rng', () => {
    const choose = duelReducer(createDuelState(baseConfig(2)), { type: 'ANIMATION_DONE' });
    expect(choose.phase).toBe('playerChoose');
    const rngBefore = choose.rng;

    const next = duelReducer(choose, { type: 'CANNON_SELECTED', cannonId: 'swivel_gun' });

    expect(next.phase).toBe('reload');
    if (next.phase !== 'reload') return;
    expect(next.cannonId).toBe('swivel_gun');
    expect(next.timerMs).toBe(getCannon('swivel_gun').timerMs);
    expect(next.question.choices).toHaveLength(4);
    const values = next.question.choices.map((c) => c.value);
    expect(new Set(values).size, 'four distinct choice values').toBe(4);
    expect(next.recentTemplateIds[0]).toBe(next.question.templateId);
    expect(next.rng).not.toEqual(rngBefore);
    expect(next.rng.state).not.toBe(rngBefore.state);
  });

  it('spec(T-020:AC-3) CANNON_SELECTED outside playerLoadout is a reference no-op', () => {
    const choose = duelReducer(createDuelState(baseConfig(3)), { type: 'ANIMATION_DONE' });
    const next = duelReducer(choose, { type: 'CANNON_SELECTED', cannonId: 'long_nine' });
    expect(next).toBe(choose);
  });

  it('spec(T-020:AC-12) resolvePlayer with both hulls > 0 + ANIMATION_DONE → rivalTurn, turnToken++, volley unchanged', () => {
    const start = resolvePlayerState({
      enemyHull: 20,
      playerHull: 80,
      turnToken: 5,
      volleyNumber: 3,
    });
    const next = duelReducer(start, { type: 'ANIMATION_DONE' });

    expect(next.phase).toBe('rivalTurn');
    expect(next.turnToken).toBe(6);
    expect(next.volleyNumber).toBe(3);
  });

  it('spec(T-020:AC-15) resolveRival with both hulls > 0 + ANIMATION_DONE → playerChoose, volley++ and turnToken++', () => {
    const start = resolveRivalState({
      enemyHull: 20,
      playerHull: 80,
      turnToken: 5,
      volleyNumber: 3,
    });
    const next = duelReducer(start, { type: 'ANIMATION_DONE' });

    expect(next.phase).toBe('playerChoose');
    expect(next.volleyNumber).toBe(4);
    expect(next.turnToken).toBe(6);
  });
});

