describe('T-020 duelReducer — answer resolution', () => {
  it('spec(T-020:AC-4) correct ANSWER_CHOSEN at 90% timer → resolvePlayer volley, hull/tally/log update', () => {
    const start = reloadState({
      cannonId: 'swivel_gun',
      enemyHull: 40,
      playerHull: PLAYER_HULL,
      tally: { correctAnswers: 0, totalAnswers: 0, perfectShots: 0, bySkill: {} },
      actionLog: [],
      rng: createRng(99),
    });
    const elapsedMs = Math.round(0.9 * start.timerMs);
    const [expectedOutcome] = resolveShot({
      cannon: getCannon('swivel_gun'),
      correct: true,
      elapsedMs,
      rng: start.rng,
    });

    const next = duelReducer(start, {
      type: 'ANSWER_CHOSEN',
      choiceIndex: start.question.correctIndex,
      elapsedMs,
    });

    expect(next.phase).toBe('resolvePlayer');
    if (next.phase !== 'resolvePlayer') return;
    expect(next.outcome.kind).toBe('volley');
    expect(next.outcome).toEqual(expectedOutcome);
    expect(next.enemyHull).toBe(start.enemyHull - expectedOutcome.damageToEnemy);
    expect(next.tally.correctAnswers).toBe(1);
    expect(next.tally.totalAnswers).toBe(1);
    expect(next.actionLog).toHaveLength(1);
    expect(next.actionLog[0]).toEqual({
      actor: 'player',
      cannonId: 'swivel_gun',
      correct: true,
      elapsedMs,
    });
  });

  it('spec(T-020:AC-5) wrong answer on volatile → misfire, recoil on player, tally attempts only', () => {
    const start = reloadState({
      cannonId: 'double_broadside',
      question: {
        ...FIXTURE_QUESTION,
        skill: 'two_step_add_sub',
        templateId: 'two_step_add_sub__fixture',
      },
      enemyHull: 40,
      playerHull: 50,
      tally: { correctAnswers: 2, totalAnswers: 3, perfectShots: 0, bySkill: {} },
      actionLog: [],
      rng: createRng(50),
    });
    const elapsedMs = 4000;
    const recoil = getCannon('double_broadside').recoilDamage;
    expect(recoil).toBeGreaterThan(0);
    const [expectedOutcome] = resolveShot({
      cannon: getCannon('double_broadside'),
      correct: false,
      elapsedMs,
      rng: start.rng,
    });

    const next = duelReducer(start, {
      type: 'ANSWER_CHOSEN',
      choiceIndex: wrongIndex(start.question),
      elapsedMs,
    });

    expect(next.phase).toBe('resolvePlayer');
    if (next.phase !== 'resolvePlayer') return;
    expect(next.outcome.kind).toBe('misfire');
    expect(next.outcome).toEqual(expectedOutcome);
    expect(next.enemyHull).toBe(40);
    expect(next.playerHull).toBe(50 - expectedOutcome.damageToSelf);
    expect(next.playerHull).toBe(50 - recoil);
    expect(next.tally.totalAnswers).toBe(4);
    expect(next.tally.correctAnswers).toBe(2);
    expect(next.actionLog).toHaveLength(1);
    expect(next.actionLog[0]?.correct).toBe(false);
    expect(next.actionLog[0]?.actor).toBe('player');
  });

  it('spec(T-020:AC-6) wrong answer on reliable → both hulls unchanged, phase resolvePlayer', () => {
    const start = reloadState({
      cannonId: 'swivel_gun',
      enemyHull: 40,
      playerHull: 50,
      rng: createRng(51),
    });

    const next = duelReducer(start, {
      type: 'ANSWER_CHOSEN',
      choiceIndex: wrongIndex(start.question),
      elapsedMs: 4000,
    });

    expect(next.phase).toBe('resolvePlayer');
    expect(next.playerHull).toBe(50);
    expect(next.enemyHull).toBe(40);
  });

  it('spec(T-020:AC-7) TIMER_EXPIRED deeply equals wrong ANSWER_CHOSEN at elapsedMs === timerMs', () => {
    const start = reloadState({
      cannonId: 'swivel_gun',
      enemyHull: 40,
      playerHull: 50,
      tally: { correctAnswers: 0, totalAnswers: 0, perfectShots: 0, bySkill: {} },
      actionLog: [],
      rng: createRng(52),
    });
    // Same starting state object must not be shared — clone via JSON so each path starts equal.
    const forTimeout = JSON.parse(JSON.stringify(start)) as typeof start;
    const forWrong = JSON.parse(JSON.stringify(start)) as typeof start;

    const viaTimeout = duelReducer(forTimeout, { type: 'TIMER_EXPIRED' });
    const viaWrong = duelReducer(forWrong, {
      type: 'ANSWER_CHOSEN',
      choiceIndex: wrongIndex(forWrong.question),
      elapsedMs: forWrong.timerMs,
    });

    expect(viaTimeout).toEqual(viaWrong);
    if (viaTimeout.phase === 'resolvePlayer') {
      expect(viaTimeout.actionLog[0]?.elapsedMs).toBe(start.timerMs);
    }
    if (viaWrong.phase === 'resolvePlayer') {
      expect(viaWrong.actionLog[0]?.elapsedMs).toBe(start.timerMs);
    }
  });

  it('spec(T-020:AC-8) ANSWER_CHOSEN with out-of-range choiceIndex or negative elapsedMs is a reference no-op', () => {
    const start = reloadState();

    expect(duelReducer(start, { type: 'ANSWER_CHOSEN', choiceIndex: -1, elapsedMs: 100 })).toBe(start);
    expect(duelReducer(start, { type: 'ANSWER_CHOSEN', choiceIndex: 4, elapsedMs: 100 })).toBe(start);
    expect(duelReducer(start, { type: 'ANSWER_CHOSEN', choiceIndex: 99, elapsedMs: 100 })).toBe(start);
    expect(duelReducer(start, { type: 'ANSWER_CHOSEN', choiceIndex: 0, elapsedMs: -1 })).toBe(start);
  });

  it('spec(T-020:AC-9) correct answer inside perfect window → perfectShot, tally, ballCount', () => {
    const start = reloadState({
      cannonId: 'swivel_gun',
      tally: { correctAnswers: 0, totalAnswers: 0, perfectShots: 0, bySkill: {} },
      rng: createRng(53),
    });
    const boundary = PERFECT_SHOT_TIMER_FRACTION * start.timerMs;
    const elapsedMs = boundary - 1;
    expect(elapsedMs).toBeLessThan(boundary);
    const [expectedOutcome] = resolveShot({
      cannon: getCannon('swivel_gun'),
      correct: true,
      elapsedMs,
      rng: start.rng,
    });

    const next = duelReducer(start, {
      type: 'ANSWER_CHOSEN',
      choiceIndex: start.question.correctIndex,
      elapsedMs,
    });

    expect(next.phase).toBe('resolvePlayer');
    if (next.phase !== 'resolvePlayer') return;
    expect(next.outcome).toEqual(expectedOutcome);
    expect(next.outcome.perfectShot).toBe(true);
    expect(next.tally.perfectShots).toBe(1);
    expect(next.outcome.ballCount).toBe(BASE_BALLS_PER_VOLLEY + 1);
  });
});

