// AC-10, AC-11, AC-23 — terminals and clamping
// =============================================================================================

describe('T-020 duelReducer — terminals and hull clamp', () => {
  it('spec(T-020:AC-10) resolvePlayer with enemyHull <= 0 + ANIMATION_DONE → victory result', () => {
    const tally = {
      correctAnswers: 4,
      totalAnswers: 4,
      perfectShots: 2,
      bySkill: { add_within_10: { correct: 4, attempts: 4 } },
    };
    const start = resolvePlayerState({
      enemyHull: 0,
      playerHull: 60,
      volleyNumber: 4,
      tally,
      actionLog: [],
    });

    const next = duelReducer(start, { type: 'ANIMATION_DONE' });

    expect(next.phase).toBe('victory');
    if (next.phase !== 'victory') return;
    expect(next.result.won).toBe(true);
    expect(next.result.tally).toEqual(tally);
    expect(next.result.volleys).toBe(4);
    expect(next.enemyHull).toBe(0);
  });

  it('spec(T-020:AC-11) resolvePlayer after volatile recoil to 0 + ANIMATION_DONE → defeat', () => {
    const start = resolvePlayerState({
      cannonId: 'double_broadside',
      enemyHull: 30,
      playerHull: 0,
      outcome: resolveShot({
        cannon: getCannon('double_broadside'),
        correct: false,
        elapsedMs: 1000,
        rng: createRng(8),
      })[0],
    });

    const next = duelReducer(start, { type: 'ANIMATION_DONE' });

    expect(next.phase).toBe('defeat');
    if (next.phase !== 'defeat') return;
    expect(next.result.won).toBe(false);
    expect(next.playerHull).toBe(0);
  });

  it('spec(T-020:AC-11) resolveRival with playerHull <= 0 + ANIMATION_DONE → defeat', () => {
    const tally = {
      correctAnswers: 2,
      totalAnswers: 3,
      perfectShots: 0,
      bySkill: { add_within_10: { correct: 2, attempts: 3 } },
    };
    const start = resolveRivalState({
      enemyHull: 28,
      playerHull: 0,
      volleyNumber: 3,
      damageToPlayer: 12,
      tally,
    });

    const next = duelReducer(start, { type: 'ANIMATION_DONE' });

    expect(next.phase).toBe('defeat');
    if (next.phase !== 'defeat') return;
    expect(next.result.won).toBe(false);
    expect(next.result.tally).toEqual(tally);
    expect(next.result.volleys).toBe(3);
    expect(next.playerHull).toBe(0);
    expect(next.enemyHull).toBe(28);
  });

  it('spec(T-020:AC-10) resolveRival with enemyHull <= 0 + ANIMATION_DONE → victory', () => {
    const tally = {
      correctAnswers: 4,
      totalAnswers: 4,
      perfectShots: 1,
      bySkill: { add_within_10: { correct: 4, attempts: 4 } },
    };
    // Enemy-first terminal order: even with playerHull already 0, enemyHull <= 0 wins.
    // The pure continue-symmetric case keeps playerHull > 0.
    const start = resolveRivalState({
      enemyHull: 0,
      playerHull: 40,
      volleyNumber: 4,
      damageToPlayer: 0,
      tally,
    });

    const next = duelReducer(start, { type: 'ANIMATION_DONE' });

    expect(next.phase).toBe('victory');
    if (next.phase !== 'victory') return;
    expect(next.result.won).toBe(true);
    expect(next.result.tally).toEqual(tally);
    expect(next.result.volleys).toBe(4);
    expect(next.enemyHull).toBe(0);
  });

  it('spec(T-020:AC-23) overkill clamps at damage application (resolvePlayer / resolveRival), not at terminal', () => {
    const playerReload = reloadState({
      cannonId: 'swivel_gun',
      enemyHull: 5,
      playerHull: 80,
      rng: createRng(60),
      tally: { correctAnswers: 0, totalAnswers: 0, perfectShots: 0, bySkill: {} },
      actionLog: [],
    });
    const [expected] = resolveShot({
      cannon: getCannon('swivel_gun'),
      correct: true,
      elapsedMs: PERFECT_ELAPSED_MS,
      rng: playerReload.rng,
    });
    expect(expected.damageToEnemy).toBeGreaterThan(5);

    const afterPlayer = duelReducer(playerReload, {
      type: 'ANSWER_CHOSEN',
      choiceIndex: playerReload.question.correctIndex,
      elapsedMs: PERFECT_ELAPSED_MS,
    });
    expect(afterPlayer.phase).toBe('resolvePlayer');
    expect(afterPlayer.enemyHull).toBe(0);
    expect(afterPlayer.enemyHull).toBeGreaterThanOrEqual(0);

    const rivalStart = rivalTurnState({
      playerHull: 3,
      enemyHull: 40,
      rng: createRng(61),
      actionLog: [],
      tally: { correctAnswers: 1, totalAnswers: 1, perfectShots: 0, bySkill: {} },
    });
    const rivalVolley: RivalVolley = {
      cannonId: 'six_pounder',
      correct: true,
      elapsedMs: PERFECT_ELAPSED_MS,
    };
    const [rivalOutcome] = resolveShot({
      cannon: getCannon('six_pounder'),
      correct: true,
      elapsedMs: PERFECT_ELAPSED_MS,
      rng: rivalStart.rng,
    });
    expect(rivalOutcome.damageToEnemy).toBeGreaterThan(3);

    const afterRival = duelReducer(rivalStart, { type: 'RIVAL_ACTION', volley: rivalVolley });
    expect(afterRival.phase).toBe('resolveRival');
    expect(afterRival.playerHull).toBe(0);
    expect(afterRival.playerHull).toBeGreaterThanOrEqual(0);
  });
});

