describe('T-020 duelReducer — rival turn', () => {
  it('spec(T-020:AC-13) correct RIVAL_ACTION → resolveRival, damages player, logs rival, tally unchanged', () => {
    const start = rivalTurnState({
      playerHull: 80,
      tally: { correctAnswers: 2, totalAnswers: 3, perfectShots: 1, bySkill: {} },
      actionLog: [{ actor: 'player', cannonId: 'swivel_gun', correct: true, elapsedMs: 900 }],
      rng: createRng(70),
    });
    const volley: RivalVolley = {
      cannonId: 'six_pounder',
      correct: true,
      elapsedMs: 1200,
    };
    const [outcome] = resolveShot({
      cannon: getCannon('six_pounder'),
      correct: true,
      elapsedMs: 1200,
      rng: start.rng,
    });

    const next = duelReducer(start, { type: 'RIVAL_ACTION', volley });

    expect(next.phase).toBe('resolveRival');
    if (next.phase !== 'resolveRival') return;
    expect(next.playerHull).toBe(start.playerHull - outcome.damageToEnemy);
    expect(next.damageToPlayer).toBe(outcome.damageToEnemy);
    expect(next.actionLog).toHaveLength(2);
    expect(next.actionLog[1]).toEqual({
      actor: 'rival',
      cannonId: volley.cannonId,
      correct: volley.correct,
      elapsedMs: volley.elapsedMs,
    });
    expect(next.tally.totalAnswers).toBe(3);
    expect(next.tally.correctAnswers).toBe(2);
  });

  it('spec(T-020:AC-14) RIVAL_ACTION naming a cannon outside rivalLoadout is a reference no-op', () => {
    const start = rivalTurnState();
    const next = duelReducer(start, {
      type: 'RIVAL_ACTION',
      volley: { cannonId: 'long_nine', correct: true, elapsedMs: 500 },
    });
    expect(next).toBe(start);
  });
});

// =============================================================================================
// AC-16, AC-17 — exhaustive no-ops and frozen terminals
// =============================================================================================

describe('T-020 duelReducer — no-op contract', () => {
  it('spec(T-020:AC-16) dod(T-020:5) exhaustive 8×5 out-of-phase matrix returns identical references', () => {
    const states = stateByPhase();
    const events = sampleEvents();

    for (const phase of EXPECTED_PHASES) {
      const state = states[phase];
      const allowed = new Set(IN_PHASE_EVENTS[phase]);
      for (const eventType of EXPECTED_EVENT_TYPES) {
        if (allowed.has(eventType)) continue;
        const result = duelReducer(state, events[eventType]);
        expect(result, `${phase} + ${eventType} must be reference-identical`).toBe(state);
      }
    }
  });

  it('spec(T-020:AC-17) victory and defeat ignore every event (frozen duel)', () => {
    const states = stateByPhase();
    const events = sampleEvents();

    for (const phase of ['victory', 'defeat'] as const) {
      const state = states[phase];
      for (const eventType of EXPECTED_EVENT_TYPES) {
        expect(duelReducer(state, events[eventType]), `${phase} + ${eventType}`).toBe(state);
      }
    }
  });
});

