// AC-18…AC-20 — scripted duel, determinism, mid-duel serialisation
// =============================================================================================

describe('T-020 duelReducer — scripted duel paths', () => {
  it('spec(T-020:AC-18) four correct player volleys vs port_sumwich hull → victory, alternating log', () => {
    expect(ENEMY_HULL_BY_ISLAND.port_sumwich).toBe(45);
    const end = driveScriptedDuel();

    expect(end.phase).toBe('victory');
    if (end.phase !== 'victory') return;
    expect(end.result.won).toBe(true);
    expect(end.result.volleys).toBe(4);
    expect(end.enemyHull).toBe(0);
    expect(end.playerHull).toBe(PLAYER_HULL);

    const actors = end.actionLog.map((e) => e.actor);
    expect(actors).toEqual(['player', 'rival', 'player', 'rival', 'player', 'rival', 'player']);
    expect(end.actionLog.filter((e) => e.actor === 'player')).toHaveLength(4);
    expect(end.actionLog.filter((e) => e.actor === 'rival')).toHaveLength(3);
  });

  it('spec(T-020:AC-19) same config + event sequence replayed 20× → identical final states', () => {
    const finals: DuelState[] = [];
    for (let i = 0; i < 20; i += 1) {
      finals.push(driveScriptedDuel());
    }
    for (let i = 1; i < finals.length; i += 1) {
      expect(finals[i]).toEqual(finals[0]);
    }
  });

  it('spec(T-020:AC-20) JSON round-trip of any mid-duel state then next event matches live path', () => {
    // Walk the live path, and at every reachable pre-event state verify round-trip + next event.
    let live: DuelState = createDuelState(baseConfig(SCRIPTED_DUEL_SEED));
    const plan: DuelEvent[] = [];

    // Build the full event list by probing questions as we go on a dry run first.
    {
      let s: DuelState = createDuelState(baseConfig(SCRIPTED_DUEL_SEED));
      const push = (e: DuelEvent): void => {
        plan.push(e);
        s = duelReducer(s, e);
      };
      push({ type: 'ANIMATION_DONE' });
      for (let volley = 1; volley <= 4; volley += 1) {
        push({ type: 'CANNON_SELECTED', cannonId: 'swivel_gun' });
        if (s.phase !== 'reload') throw new Error('expected reload');
        push({
          type: 'ANSWER_CHOSEN',
          choiceIndex: s.question.correctIndex,
          elapsedMs: PERFECT_ELAPSED_MS,
        });
        push({ type: 'ANIMATION_DONE' });
        if (volley < 4) {
          push({
            type: 'RIVAL_ACTION',
            volley: {
              cannonId: 'six_pounder',
              correct: false,
              elapsedMs: RIVAL_MISS_ELAPSED_MS,
            },
          });
          push({ type: 'ANIMATION_DONE' });
        }
      }
    }

    for (let i = 0; i < plan.length; i += 1) {
      const event = plan[i]!;
      const viaLive = duelReducer(live, event);
      const revived = JSON.parse(JSON.stringify(live)) as DuelState;
      const viaRoundTrip = duelReducer(revived, event);
      expect(viaRoundTrip, `step ${i} ${event.type}`).toEqual(viaLive);
      live = viaLive;
    }
  });
});

