// =============================================================================================
// AC-22 — non-mutation
// =============================================================================================

describe('T-020 duelReducer — purity / immutability', () => {
  it('spec(T-020:AC-22) every table transition leaves the input object and its arrays unmutated', () => {
    const reloadForAnswer = toReload(23, 'swivel_gun');
    const reloadForTimeout = toReload(24, 'swivel_gun');
    const transitions: readonly { readonly state: DuelState; readonly event: DuelEvent }[] = [
      {
        state: createDuelState(baseConfig(22)),
        event: { type: 'ANIMATION_DONE' },
      },
      {
        state: duelReducer(createDuelState(baseConfig(22)), { type: 'ANIMATION_DONE' }),
        event: { type: 'CANNON_SELECTED', cannonId: 'swivel_gun' },
      },
      {
        state: reloadForAnswer,
        event: {
          type: 'ANSWER_CHOSEN',
          choiceIndex: reloadForAnswer.question.correctIndex,
          elapsedMs: 5000,
        },
      },
      {
        state: reloadForTimeout,
        event: { type: 'TIMER_EXPIRED' },
      },
      {
        state: resolvePlayerState({ enemyHull: 20, playerHull: 80 }),
        event: { type: 'ANIMATION_DONE' },
      },
      {
        state: rivalTurnState({ rng: createRng(25) }),
        event: {
          type: 'RIVAL_ACTION',
          volley: { cannonId: 'six_pounder', correct: false, elapsedMs: 1000 },
        },
      },
      {
        state: resolveRivalState({ enemyHull: 20, playerHull: 80 }),
        event: { type: 'ANIMATION_DONE' },
      },
    ];

    for (const { state, event } of transitions) {
      const jsonBefore = JSON.stringify(state);
      const arrays = snapshotArrays(state);

      const next = duelReducer(state, event);
      expect(next, `${state.phase} + ${event.type}`).not.toBe(state);
      expect(JSON.stringify(state), `${state.phase} input mutated`).toBe(jsonBefore);
      expect(state.playerLoadout).toBe(arrays.playerLoadout);
      expect(state.rivalLoadout).toBe(arrays.rivalLoadout);
      expect(state.recentTemplateIds).toBe(arrays.recentTemplateIds);
      expect(state.actionLog).toBe(arrays.actionLog);
      if (state.phase === 'reload' && arrays.choices) {
        expect(state.question.choices).toBe(arrays.choices);
      }
    }
  });
});

// =============================================================================================
// AC-24 — literal enumerations in THIS file
// =============================================================================================

describe('T-020 duelReducer — test-file structure', () => {
  it('spec(T-020:AC-24) phase and event enumerations are hardcoded literals, not derived', () => {
    const literalBlock = (name: string): readonly string[] => {
      const match = new RegExp(`const ${name} = \\[([^\\]]*)\\] as const;`).exec(OWN_SOURCE);
      expect(match, `${name} must be an inline array literal ending in "as const"`).not.toBeNull();
      return (match?.[1] ?? '')
        .split(',')
        .map((line) => line.trim())
        .filter((line) => line.length > 0);
    };

    const phaseEntries = literalBlock('EXPECTED_PHASES');
    const eventEntries = literalBlock('EXPECTED_EVENT_TYPES');

    for (const entry of [...phaseEntries, ...eventEntries]) {
      expect(entry).toMatch(/^'[A-Za-z_]+'$/);
    }
    expect(phaseEntries.map((e) => e.slice(1, -1))).toEqual([...EXPECTED_PHASES]);
    expect(eventEntries.map((e) => e.slice(1, -1))).toEqual([...EXPECTED_EVENT_TYPES]);

    // No derivation from the production exports.
    expect(OWN_SOURCE).not.toMatch(/EXPECTED_PHASES\s*=\s*DUEL_PHASES/);
    expect(OWN_SOURCE).not.toMatch(/EXPECTED_PHASES\s*=\s*\[\s*\.\.\.DUEL_PHASES/);
    expect(OWN_SOURCE).not.toMatch(/EXPECTED_EVENT_TYPES\s*=\s*\[.*DuelEvent/);
    expect(OWN_SOURCE.includes('DUEL_PHASES.map')).toBe(false);
  });
});

