describe('T-020 Definition of Done', () => {
  it('dod(T-020:1) tags a test against every acceptance criterion the ticket declares', () => {
    const declared = [...TICKET_SOURCE.matchAll(/\*\*(AC-\d+)\*\*/g)].map((match) => match[1]);
    const unique = [...new Set(declared)];
    const untagged = unique.filter((ac) => !OWN_SOURCE.includes(`spec(T-020:${ac})`));

    expect(unique.length).toBe(24);
    expect(untagged).toEqual([]);
  });

  it('dod(T-020:2) keeps local gates wired and this suite free of skip/only markers', () => {
    const gates = readFileSync(join(REPO_ROOT, '.tdd-swarm/run-local-gates.sh'), 'utf8');
    for (const command of ['prettier --check', 'eslint . --max-warnings 0', 'tsc --noEmit', 'vitest run']) {
      expect(gates, `run-local-gates.sh must still run: ${command}`).toContain(command);
    }
    for (const marker of DEFERRED_WORK_MARKERS) {
      expect(OWN_SOURCE.includes(marker), `suite must not contain ${marker}`).toBe(false);
    }
    expect(FOCUSED_TEST_PATTERN.test(OWN_SOURCE)).toBe(false);
  });

  it('dod(T-020:3) numbers every dod tag so spec-lint covers all eight DoD items', () => {
    const dodCount = (TICKET_SOURCE.match(/^- \[[ x]\] /gm) ?? []).length;
    const tagged = [...OWN_SOURCE.matchAll(/dod\(T-020:([^)]*)\)/g)].map((match) => match[1] ?? '');
    const unparseable = tagged.filter((id) => !/^\d+$/.test(id));
    const covered = new Set(tagged.filter((id) => /^\d+$/.test(id)).map(Number));
    const missing = Array.from({ length: dodCount }, (_, i) => i + 1).filter((n) => !covered.has(n));

    expect(dodCount).toBe(8);
    expect(unparseable).toEqual([]);
    expect(missing).toEqual([]);
    expect(OWN_SOURCE).toContain('spec(T-020:AC-');
  });

  it('dod(T-020:4) duelReducer is a two-arg pure sync function with no Math.random/Date/await/React', () => {
    expect(typeof duelReducer).toBe('function');
    expect(duelReducer.length).toBe(2);

    expect(existsSync(REDUCER_SRC_PATH)).toBe(true);
    const source = readFileSync(REDUCER_SRC_PATH, 'utf8');
    expect(source).not.toMatch(/\bMath\.random\b/);
    expect(source).not.toMatch(/\bDate\b/);
    expect(source).not.toMatch(/\bawait\b/);
    expect(source).not.toMatch(/from ['"]react['"]/);
    expect(source).not.toMatch(/from ['"]react\//);
  });

  it('dod(T-020:6) hulls clamp at apply-time and tally counts player answers only', () => {
    // Behaviour is pinned by AC-13 + AC-23; this DoD tag keeps spec-lint coverage honest.
    expect(OWN_SOURCE).toContain('spec(T-020:AC-13)');
    expect(OWN_SOURCE).toContain('spec(T-020:AC-23)');
  });

  it('dod(T-020:7) damage flows through @engine/duel/damage — no local damage arithmetic', () => {
    expect(existsSync(REDUCER_SRC_PATH)).toBe(true);
    const source = readFileSync(REDUCER_SRC_PATH, 'utf8');
    expect(source).toMatch(/resolveShot/);
    expect(source).toMatch(/@engine\/duel\/damage/);
    expect(source).not.toMatch(/damageMin\s*\*|damageMax\s*\*/);
    expect(source).not.toMatch(/PERFECT_SHOT_BONUS_DAMAGE/);
    expect(source).not.toMatch(/ANSWER_QUALITY_FLOOR/);
  });

  it('dod(T-020:8) production file for this ticket is src/engine/duel/reducer.ts', () => {
    expect(existsSync(REDUCER_SRC_PATH), 'implementer must create reducer.ts').toBe(true);
    const present = readdirSync(DUEL_DIR)
      .filter((name) => name.endsWith('.ts'))
      .sort();
    // Prior tickets own types.ts + damage.ts; this ticket adds exactly reducer.ts.
    expect(present).toEqual(['damage.ts', 'reducer.ts', 'types.ts']);
  });
});
